<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · WheelMenuButton</h1>
      <p class="demo-page__lead">
        来自 video-code 的「轮盘按钮」：一颗圆按钮，点一下绕圆环弹出 7 个子按钮，主按钮同时转 360°
        并把「展开」换成「收起」。原 demo 是固定在页面正中的纯展示，组件里补了两件实际使用时必须有的能力：
        <b>可拖拽</b>（Pointer Events，鼠标 / 触摸 / 触控笔同一套）和<b>防误触</b>（位移超过阈值才算拖拽，
        拖完吞掉随之而来的 click，只有真正点一下才切换菜单）。
      </p>
    </header>

    <section class="wb-demo">
      <div class="wb-demo__head">
        <h2 class="demo-page__section-title">拖一拖，再点一下</h2>
        <code class="wb-demo__tag">drag / click</code>
      </div>
      <p class="demo-card__text">
        页面里有两颗悬浮球：一颗在示例区（下面这张卡片附近），一颗在属性面板里（默认停在右下角）。
        按住任意一颗拖动可以放到任意位置，松手不会误触发菜单；停在原地轻点一下才展开，再点一下收起。
        展开状态下拖动，整个圆环会跟着走。拖动范围会给展开的圆环留出余量，所以贴边也不会被屏幕裁掉；
        点空白处或按 Esc 也能收起。
      </p>

      <div class="wb-demo__toolbar">
        <button class="demo-btn" type="button" @click="wheelRef?.open()">打开菜单</button>
        <button class="demo-btn demo-btn--ghost" type="button" @click="wheelRef?.close()">收起</button>
        <button class="demo-btn demo-btn--ghost" type="button" @click="moveHome">移回右下角</button>
      </div>

      <div class="wb-demo__stage">
        <div class="wb-demo__card">
          <p class="wb-demo__card-title">这块是「页面内容」</p>
          <p class="wb-demo__card-text">
            悬浮球浮在视口里，不占文档流。试着把它拖到这块卡片上再点开，菜单会盖在内容上面；
            拖到最边上时，圆环会自动往里让一点。
          </p>
        </div>

        <WheelMenuButton
          ref="wheelRef"
          v-model:open="opened"
          :initial-x="640"
          :initial-y="720"
          @select="onSelect"
          @drag-end="onDragEnd"
        />
      </div>

      <p class="wb-demo__hint">
        最近选中的是：<code>{{ picked }}</code> · 最近落点：<code>{{ dragPosition }}</code> ·
        菜单：<code>{{ opened ? '展开' : '收起' }}</code>
      </p>
    </section>

    <DemoPreview class="wb-preview">
      <LevaPlayground
        name="WheelMenuButton"
        :component="WheelMenuButton"
        :schema="WheelMenuButtonSchema"
        :presets="{}"
        :listeners="{
          select: (item: { label?: string }) => (picked = item.label || ''),
          'drag-end': (position: { x: number; y: number }) =>
            (dragPosition = `${Math.round(position.x)}, ${Math.round(position.y)}`),
        }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>size</code> / <code>itemSize</code> / <code>radius</code> 调尺寸，
        <code>dragThreshold</code> 是「算拖拽还是算点击」的位移阈值（调大到 20 就更难触发拖拽），
        <code>edgeMargin</code> 是贴边留白，<code>duration</code> 是展开动画时长，
        <code>draggable</code> 关掉就只能点、不能拖。
        <code>items</code> 是数组（面板不生成控件），要换菜单项直接传 <code>:items="[...]"</code>。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import WheelMenuButtonSchema from '@melt-js/comps-vue3/src/components/WheelMenuButton.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const WheelMenuButton = remoteComponent('WheelMenuButton')

const wheelRef = ref<{ open: () => void; close: () => void; moveTo: (x: number, y: number) => void } | null>(
  null,
)
const opened = ref(false)
const picked = ref('（还没选）')
const dragPosition = ref('（还没拖过）')

const stageStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  height: '420px',
  padding: '24px',
  background: 'radial-gradient(circle at center, #f9f9f9, #e9e9e9)',
}

function onSelect(item: { label?: string }) {
  picked.value = item.label || '（无文案）'
}

function onDragEnd(position: { x: number; y: number }) {
  dragPosition.value = `${Math.round(position.x)}, ${Math.round(position.y)}`
}

function moveHome() {
  wheelRef.value?.moveTo(window.innerWidth - 56, window.innerHeight - 56)
}
</script>

